/**
 * BR-106: SQL for physical stock verifications. Every function takes an `Executor` so the service
 * can run each state change as ONE transaction; no authorization decision lives here.
 *
 * A verification never writes stock: `system_qty` is a snapshot of the ledger-derived balance, and
 * `variance_qty` is GENERATED by the database. A variance reaches the ledger only through a
 * COUNT_CORRECTION stock adjustment that someone else approves (BR-37).
 *
 * `inventory_batches.source_farmer_id` is never selected (BR-16).
 */
import type { Executor } from '../../db/pool.js';
import type { AdjustmentStatus } from '../stock-adjustments/stock-adjustments.schema.js';
import type { ListVerificationsQuery, StockVerification, VerificationStatus } from './stock-verifications.schema.js';

export interface CountableBatch {
  id: string;
  warehouseId: string;
  /** numeric(12,3) as text: the ledger-derived balance at the moment of the read. */
  qtyAvailableKg: string;
}

export interface NewVerification {
  warehouseId: string;
  batchId: string;
  systemQtyKg: string;
  countedQtyKg: string;
  status: VerificationStatus;
  notes: string | null;
  verifiedBy: string;
}

export interface StockVerificationsRepo {
  /** The batch, share-locked so no ledger row lands between the snapshot and the insert. */
  lockBatchForCount(db: Executor, batchId: string): Promise<CountableBatch | null>;
  insertVerification(db: Executor, input: NewVerification): Promise<string>;
  findVerification(db: Executor, id: string): Promise<StockVerification | null>;
  lockVerification(db: Executor, id: string): Promise<StockVerification | null>;
  list(
    db: Executor,
    query: ListVerificationsQuery,
    visibleWarehouses: string[] | null,
  ): Promise<{ items: StockVerification[]; total: number }>;
  /** Links the raised adjustment and marks the verification RECONCILED. */
  linkAdjustment(db: Executor, id: string, adjustmentId: string): Promise<void>;
}

interface VerificationRow {
  id: string;
  warehouse_id: string;
  batch_id: string;
  batch_code: string;
  crop_id: string;
  grade: string;
  system_qty: string;
  counted_qty: string;
  variance_qty: string;
  status: VerificationStatus;
  notes: string | null;
  verified_by: string;
  verified_at: Date;
  adjustment_id: string | null;
  adjustment_status: AdjustmentStatus | null;
  created_at: Date;
  updated_at: Date | null;
}

function toVerification(row: VerificationRow): StockVerification {
  return {
    id: row.id,
    warehouseId: row.warehouse_id,
    batchId: row.batch_id,
    batchCode: row.batch_code,
    cropId: row.crop_id,
    grade: row.grade,
    systemQtyKg: row.system_qty,
    countedQtyKg: row.counted_qty,
    varianceKg: row.variance_qty,
    status: row.status,
    notes: row.notes,
    verifiedBy: row.verified_by,
    verifiedAt: row.verified_at.toISOString(),
    adjustmentId: row.adjustment_id,
    adjustmentStatus: row.adjustment_status,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at === null ? null : row.updated_at.toISOString(),
  };
}

// The API only ever records batch-level counts, so batch_id is always present on rows it reads;
// a warehouse-level row (batch_id NULL, allowed by 0005) is excluded by the inner join.
const SELECT_VERIFICATION = `
  SELECT v.id, v.warehouse_id, v.batch_id, b.batch_code, b.crop_id, b.grade::text AS grade,
         v.system_qty::text AS system_qty, v.counted_qty::text AS counted_qty, v.variance_qty::text AS variance_qty,
         v.status, v.notes, v.verified_by, v.verified_at, v.adjustment_id, a.status AS adjustment_status,
         v.created_at, v.updated_at
    FROM stock_verifications v
    JOIN inventory_batches b ON b.id = v.batch_id
    LEFT JOIN stock_adjustments a ON a.id = v.adjustment_id`;

export const stockVerificationsRepo: StockVerificationsRepo = {
  async lockBatchForCount(db, batchId) {
    const result = await db.query<{ id: string; warehouse_id: string; qty_available: string }>(
      `SELECT id, warehouse_id, qty_available::text AS qty_available
         FROM inventory_batches
        WHERE id = $1
          FOR SHARE`,
      [batchId],
    );
    const row = result.rows[0];
    return row === undefined ? null : { id: row.id, warehouseId: row.warehouse_id, qtyAvailableKg: row.qty_available };
  },

  async insertVerification(db, input) {
    const result = await db.query<{ id: string }>(
      `INSERT INTO stock_verifications (warehouse_id, batch_id, system_qty, counted_qty, status, notes, verified_by)
       VALUES ($1, $2, $3::numeric, $4::numeric, $5, $6, $7)
       RETURNING id`,
      [input.warehouseId, input.batchId, input.systemQtyKg, input.countedQtyKg, input.status, input.notes, input.verifiedBy],
    );
    return result.rows[0]!.id;
  },

  async findVerification(db, id) {
    const result = await db.query<VerificationRow>(`${SELECT_VERIFICATION} WHERE v.id = $1`, [id]);
    const row = result.rows[0];
    return row === undefined ? null : toVerification(row);
  },

  async lockVerification(db, id) {
    const result = await db.query<VerificationRow>(`${SELECT_VERIFICATION} WHERE v.id = $1 FOR UPDATE OF v`, [id]);
    const row = result.rows[0];
    return row === undefined ? null : toVerification(row);
  },

  async list(db, query, visibleWarehouses) {
    const params: unknown[] = [];
    const conditions: string[] = [];
    if (visibleWarehouses !== null) {
      params.push(visibleWarehouses);
      conditions.push(`v.warehouse_id = ANY($${params.length}::uuid[])`);
    }
    if (query.status !== undefined) {
      params.push(query.status);
      conditions.push(`v.status = $${params.length}`);
    }
    if (query.warehouseId !== undefined) {
      params.push(query.warehouseId);
      conditions.push(`v.warehouse_id = $${params.length}::uuid`);
    }
    if (query.batchId !== undefined) {
      params.push(query.batchId);
      conditions.push(`v.batch_id = $${params.length}::uuid`);
    }
    if (query.hasVariance !== undefined) {
      conditions.push(query.hasVariance ? 'v.variance_qty <> 0' : 'v.variance_qty = 0');
    }
    const where = conditions.length === 0 ? 'TRUE' : conditions.join(' AND ');
    const count = await db.query<{ total: string }>(
      `SELECT count(*)::text AS total FROM stock_verifications v JOIN inventory_batches b ON b.id = v.batch_id WHERE ${where}`,
      params,
    );
    const rows = await db.query<VerificationRow>(
      `${SELECT_VERIFICATION} WHERE ${where}
        ORDER BY v.verified_at DESC, v.id DESC
        LIMIT $${params.length + 1} OFFSET $${params.length + 2}`,
      [...params, query.pageSize, (query.page - 1) * query.pageSize],
    );
    return { items: rows.rows.map(toVerification), total: Number(count.rows[0]?.total ?? '0') };
  },

  async linkAdjustment(db, id, adjustmentId) {
    await db.query(
      `UPDATE stock_verifications
          SET adjustment_id = $2, status = 'RECONCILED', updated_at = now()
        WHERE id = $1 AND adjustment_id IS NULL`,
      [id, adjustmentId],
    );
  },
};
